; Godot 4 project
config_version=5

[application]
config/name="Petersburg: River City"
run/main_scene="res://scenes/main.tscn"
config/features=PackedStringArray("4.2", "Forward Plus")

[display]
window/size/viewport_width=1280
window/size/viewport_height=720
window/stretch/mode="canvas_items"

[physics]
common/physics_ticks_per_second=60

[input]
move_forward={"deadzone":0.5,"events":[{"physical_keycode":87,"type":"InputEventKey","keycode":87}]}
move_back={"deadzone":0.5,"events":[{"physical_keycode":83,"type":"InputEventKey","keycode":83}]}
move_left={"deadzone":0.5,"events":[{"physical_keycode":65,"type":"InputEventKey","keycode":65}]}
move_right={"deadzone":0.5,"events":[{"physical_keycode":68,"type":"InputEventKey","keycode":68}]}
sprint={"deadzone":0.5,"events":[{"physical_keycode":4194325,"type":"InputEventKey","keycode":4194325}]}
jump={"deadzone":0.5,"events":[{"physical_keycode":32,"type":"InputEventKey","keycode":32}]}
interact={"deadzone":0.5,"events":[{"physical_keycode":69,"type":"InputEventKey","keycode":69}]}
exit_vehicle={"deadzone":0.5,"events":[{"physical_keycode":70,"type":"InputEventKey","keycode":70}]}
honk={"deadzone":0.5,"events":[{"physical_keycode":72,"type":"InputEventKey","keycode":72}]}

extends CharacterBody3D

@export var walk_speed := 5.0
@export var sprint_speed := 8.5
@export var jump_speed := 4.8
@export var mouse_sensitivity := 0.002

@onready var head: Node3D = $Head
@onready var interactor: RayCast3D = $Head/Camera3D/Interactor

var gravity := float(ProjectSettings.get_setting("physics/3d/default_gravity"))
var controls_enabled := true

func _ready() -> void:
	Input.mouse_mode = Input.MOUSE_MODE_CAPTURED

func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("ui_cancel"):
		Input.mouse_mode = Input.MOUSE_MODE_VISIBLE
	if event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_LEFT:
		Input.mouse_mode = Input.MOUSE_MODE_CAPTURED
	if event is InputEventMouseMotion and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
		rotate_y(-event.relative.x * mouse_sensitivity)
		head.rotation.x = clampf(head.rotation.x - event.relative.y * mouse_sensitivity, deg_to_rad(-85), deg_to_rad(85))

func _physics_process(delta: float) -> void:
	if not controls_enabled:
		return
	if not is_on_floor(): velocity.y -= gravity * delta
	if Input.is_action_just_pressed("jump") and is_on_floor(): velocity.y = jump_speed
	var input_dir := Input.get_vector("move_left", "move_right", "move_forward", "move_back")
	var direction := (global_transform.basis * Vector3(input_dir.x, 0, input_dir.y)).normalized()
	var speed := sprint_speed if Input.is_action_pressed("sprint") else walk_speed
	velocity.x = direction.x * speed
	velocity.z = direction.z * speed
	move_and_slide()

extends RayCast3D

const REACH := 3.0
var player_body: CharacterBody3D

func _ready() -> void:
	target_position = Vector3(0, 0, -REACH)
	enabled = true
	collide_with_bodies = true
	collide_with_areas = false
	var node: Node = self
	while node and not (node is CharacterBody3D): node = node.get_parent()
	player_body = node as CharacterBody3D
	if player_body: add_exception(player_body)

func _unhandled_input(event: InputEvent) -> void:
	if not event.is_action_pressed("interact") or not is_colliding(): return
	var target := get_collider()
	if target and target.has_meta("on_interact"):
		target.get_meta("on_interact").call(player_body)
		get_viewport().set_input_as_handled()

extends CanvasLayer

signal move_vector_changed(value: Vector2)
signal look_delta(value: Vector2)

var stick_origin := Vector2(120, 560)
var stick_pos := stick_origin
var joystick_touch := -1
var look_touch := -1
var look_last := Vector2.ZERO

func _ready():
	visible = DisplayServer.is_touchscreen_available()

func _draw():
	draw_circle(stick_origin, 65, Color(0.05, 0.05, 0.06, 0.55))
	draw_circle(stick_pos, 28, Color(0.35, 0.55, 0.85, 0.85))

func _process(_delta):
	queue_redraw()

func _input(event: InputEvent):
	if event is InputEventScreenTouch:
		if event.pressed:
			if event.position.x < get_viewport().size.x * 0.45 and joystick_touch == -1:
				joystick_touch = event.index
				stick_origin = event.position
				stick_pos = event.position
			elif look_touch == -1:
				look_touch = event.index
				look_last = event.position
		else:
			if event.index == joystick_touch:
				joystick_touch = -1
				stick_pos = stick_origin
				move_vector_changed.emit(Vector2.ZERO)
			elif event.index == look_touch:
				look_touch = -1
	elif event is InputEventScreenDrag:
		if event.index == joystick_touch:
			var delta := event.position - stick_origin
			if delta.length() > 65: delta = delta.normalized() * 65
			stick_pos = stick_origin + delta
			move_vector_changed.emit(Vector2(delta.x / 65.0, delta.y / 65.0))
		elif event.index == look_touch:
			look_delta.emit(event.relative)

func add_action_button(text: String, action: String, position: Vector2):
	var button := Button.new()
	button.text = text
	button.position = position
	button.size = Vector2(88, 88)
	button.pressed.connect(func():
		if action == "restart": get_tree().reload_current_scene()
		else:
			Input.action_press(action)
			var timer := get_tree().create_timer(0.12)
			await timer.timeout
			Input.action_release(action)
	)
	add_child(button)

extends Node3D

const PLAYER_POS := Vector3(0, 1.1, 0)
var mission_active := false
var has_package := false
var time_left := 180.0
var cash := 0
var wanted := 0
var heat := 0.0
var pickup: StaticBody3D
var dropoff: Area3D
var car: VehicleBody3D
var player: CharacterBody3D
var hud: Label
var marker: MeshInstance3D
var wanted_timer := 0.0

func _ready():
	_build_world()
	_build_missions()
	_build_hud()
	_build_touch_controls()
	_load_save()
	start_mission()

func add_box(parent: Node, pos: Vector3, size: Vector3, color: Color) -> StaticBody3D:
	var body := StaticBody3D.new(); body.position = pos
	var mesh := BoxMesh.new(); mesh.size = size
	var mat := StandardMaterial3D.new(); mat.albedo_color = color; mesh.material = mat
	var mi := MeshInstance3D.new(); mi.mesh = mesh; body.add_child(mi)
	var shape := BoxShape3D.new(); shape.size = size
	var col := CollisionShape3D.new(); col.shape = shape; body.add_child(col)
	parent.add_child(body)
	return body

func _build_world():
	var env := WorldEnvironment.new(); var environment := Environment.new()
	environment.background_mode = Environment.BG_SKY
	environment.ambient_light_source = Environment.AMBIENT_SOURCE_SKY
	environment.ambient_light_energy = 0.8
	environment.fog_enabled = true; environment.fog_density = 0.002
	env.environment = environment; add_child(env)
	var light := DirectionalLight3D.new(); light.rotation_degrees = Vector3(-55, -35, 0); light.shadow_enabled = true; add_child(light)
	add_box(self, Vector3(0, -0.5, 0), Vector3(200, 1, 200), Color(0.30, 0.34, 0.29))
	add_box(self, Vector3(0, 0.015, 0), Vector3(200, 0.04, 8), Color(0.15, 0.15, 0.17))
	add_box(self, Vector3(0, 0.015, 0), Vector3(8, 0.04, 200), Color(0.15, 0.15, 0.17))
	add_box(self, Vector3(-84, -0.35, 0), Vector3(30, 0.3, 200), Color(0.10, 0.28, 0.40))
	var colors := [Color(0.55,0.24,0.17), Color(0.62,0.34,0.24), Color(0.42,0.28,0.22)]
	var xs := [-52,-38,-24,24,38,52]; var zs := [-52,-38,-24,24,38,52]
	for x in xs:
		for z in zs:
			if abs(x) < 15 and abs(z) < 15: continue
			var h := 7.0 + fmod(abs(x*z), 9.0)
			add_box($Buildings if has_node("Buildings") else self, Vector3(x,h*0.5,z), Vector3(11,h,11), colors[(abs(x)+abs(z)) % colors.size()])
	if not has_node("Buildings"):
		var buildings := Node3D.new(); buildings.name="Buildings"; add_child(buildings)
	# Add street furniture and river edge
	add_box(self, Vector3(-72,0.4,0), Vector3(1.2,0.8,190), Color(0.25,0.23,0.20))
	_build_player()
	_build_car()

func _build_player():
	var packed := load("res://scenes/player.tscn")
	player = packed.instantiate(); player.name="Player"; player.position=PLAYER_POS; add_child(player)

func _build_car():
	car = VehicleBody3D.new(); car.name="Sedan"; car.position=Vector3(8,0.7,6)
	var mesh:=BoxMesh.new(); mesh.size=Vector3(2.2,0.7,4.2)
	var mi:=MeshInstance3D.new(); mi.mesh=mesh
	var mat:=StandardMaterial3D.new(); mat.albedo_color=Color(0.15,0.25,0.50); mi.material_override=mat
	car.add_child(mi)
	var shape:=BoxShape3D.new(); shape.size=Vector3(2.2,0.7,4.2)
	var col:=CollisionShape3D.new(); col.shape=shape; car.add_child(col)
	car.set_meta("on_interact",Callable(self,"enter_car"))
	add_child(car)
	for i in range(4):
		var wheel:=VehicleWheel3D.new(); wheel.position=Vector3(-1.05 if i%2==0 else 1.05, -0.45, -1.35 if i<2 else 1.35); wheel.use_as_traction=true if i>=2 else false; wheel.use_as_steering=true if i<2 else false; car.add_child(wheel)

func enter_car(_body: Node):
	if player.global_position.distance_to(car.global_position)>4.0: return
	player.visible=false; player.controls_enabled=false
	var cam:=Camera3D.new(); cam.name="ChaseCamera"; cam.position=Vector3(0,4.5,7); cam.look_at(car.global_position); cam.current=true; car.add_child(cam)
	car.set_meta("on_interact",Callable(self,"exit_car"))

func exit_car(_body: Node):
	if car.has_node("ChaseCamera"):
		var cam:=car.get_node("ChaseCamera"); cam.queue_free()
	player.visible=true; player.controls_enabled=true
	player.global_position=car.global_position+Vector3(3,1,0)
	if player.get_node_or_null("Head/Camera3D"):
		player.get_node("Head/Camera3D").current=true
	car.set_meta("on_interact",Callable(self,"enter_car"))

func _build_missions():
	pickup=add_box(self,Vector3(-18,0.4,-15),Vector3(0.8,0.8,0.8),Color(0.95,0.72,0.12)); pickup.set_meta("on_interact",Callable(self,"pick_up"))
	dropoff=Area3D.new(); dropoff.position=Vector3(0,1.5,30)
	var shape:=BoxShape3D.new(); shape.size=Vector3(6,3,6)
	var col:=CollisionShape3D.new(); col.shape=shape; dropoff.add_child(col)
	dropoff.body_entered.connect(_dropoff_entered); add_child(dropoff)
	var m:=MeshInstance3D.new(); var box:=BoxMesh.new(); box.size=Vector3(6,0.05,6); m.mesh=box
	var mat:=StandardMaterial3D.new(); mat.albedo_color=Color(0.1,0.85,0.25); mat.transparency=BaseMaterial3D.TRANSPARENCY_ALPHA; mat.albedo_color.a=0.55; m.material_override=mat
	dropoff.add_child(m)

func start_mission():
	mission_active=true; has_package=false; time_left=180; pickup.visible=true; pickup.set_meta("on_interact",Callable(self,"pick_up"))

func pick_up(_body: Node):
	if has_package or not mission_active:return
	has_package=true; pickup.visible=false; pickup.remove_meta("on_interact")

func _dropoff_entered(body:Node):
	if mission_active and has_package and (body is CharacterBody3D or body is VehicleBody3D): complete_mission()

func complete_mission():
	mission_active=false; cash+=250; _save(); start_mission()

func fail_mission():
	mission_active=false; start_mission()

func _process(delta):
	if mission_active:
		time_left-=delta
		if time_left<=0: fail_mission()
	wanted_timer-=delta
	if wanted>0 and wanted_timer<=0:
		wanted_timer=5
		if heat>0: heat=max(0,heat-delta*0.3)
		else: wanted=max(0,wanted-1)
	_update_hud()

func _unhandled_input(event):
	if event is InputEventKey and event.pressed and event.keycode==KEY_R: get_tree().reload_current_scene()
	if event.is_action_pressed("exit_vehicle") and player and not player.controls_enabled: exit_car(player)

func _build_hud():
	var layer:=CanvasLayer.new(); add_child(layer); hud=Label.new(); hud.position=Vector2(24,24); hud.add_theme_font_size_override("font_size",20); hud.add_theme_color_override("font_outline_color",Color.BLACK); hud.add_theme_constant_override("outline_size",6); layer.add_child(hud)

func _update_hud():
	var status="Pickup crate: warehouse (-18, -15)" if not has_package else "Deliver to green zone: Market Street (0, 30)"
	hud.text="PETERSBURG: RIVER CITY\n%s\nTime %03d  Cash $%d  Wanted %d/5" %[status,ceil(time_left),cash,wanted]

func _build_touch_controls():
	var tc_script:=load("res://scripts/touch_controls.gd")
	var tc:=tc_script.new(); tc.name="TouchControls"; add_child(tc)
	tc.add_action_button("JUMP","jump",Vector2(1180,520))
	tc.add_action_button("E","interact",Vector2(1080,520))
	tc.add_action_button("F","exit_vehicle",Vector2(1180,620))
	tc.add_action_button("R","restart",Vector2(1080,620))

func _save():
	var data={"cash":cash}
	var file:=FileAccess.open("user://petersburg_save.json",FileAccess.WRITE); file.store_string(JSON.stringify(data))

func _load_save():
	if not FileAccess.file_exists("user://petersburg_save.json"): return
	var file:=FileAccess.open("user://petersburg_save.json",FileAccess.READ)
	var data=JSON.parse_string(file.get_as_text())
	if typeof(data)==TYPE_DICTIONARY and data.has("cash"): cash=int(data.cash)

class_name Vehicle
extends CharacterBody3D

## Arcade vehicle: readable handling, real collisions, animated wheels and
## optional AI driving. The same body is used for parked cars, traffic and
## police units.

var game: Node
var vehicle_type := "sedan"
var body_color := Color(0.2, 0.3, 0.5)
var is_police := false
var is_taxi := false
var driver: Node = null
var parked := true
var autopilot := false
var is_player_driven := false

var speed := 0.0
var max_speed := 25.0
var reverse_speed := 9.0
var accel := 11.0
var brake_force := 24.0
var steer_rate := 1.9
var wheel_spin := 0.0
var wheel_radius := 0.34
var health := 100.0
var night := false

var model_data: Dictionary = {}
var steer_wheels: Array = []
var spin_wheels: Array = []
var chase_camera: Camera3D
var headlight_spot: SpotLight3D
var engine_audio: AudioStreamPlayer3D
var siren_audio: AudioStreamPlayer3D
var siren_red: MeshInstance3D
var siren_blue: MeshInstance3D
var siren_time := 0.0
var horn_cooldown := 0.0
var crash_cooldown := 0.0
var route: Array = []
var route_index := 0
var ai_target: Node3D = null
var ai_stuck := 0.0

func setup(g: Node, type: String, color: Color, opts := {}) -> void:
	game = g
	vehicle_type = type
	body_color = color
	is_police = bool(opts.get("police", false))
	is_taxi = type == "taxi"
	collision_layer = 4
	collision_mask = 1 | 2 | 4 | 8
	up_direction = Vector3.UP
	floor_snap_length = 0.4
	motion_mode = CharacterBody3D.MOTION_MODE_FLOATING
	model_data = VehicleModel.build(self, type, color)
	var size: Vector3 = model_data.get("size", Vector3(1.9, 1.4, 4.4))
	wheel_radius = float(model_data.get("wheel_radius", 0.34))
	steer_wheels = model_data.get("steer_wheels", [])
	spin_wheels = model_data.get("spin_wheels", [])
	siren_red = model_data.get("siren_red", null)
	siren_blue = model_data.get("siren_blue", null)

	var col := CollisionShape3D.new()
	var shape := BoxShape3D.new()
	shape.size = Vector3(size.x, maxf(0.9, size.y * 0.82), size.z)
	col.shape = shape
	col.position.y = shape.size.y * 0.5 + 0.05
	add_child(col)

	chase_camera = Camera3D.new()
	chase_camera.name = "ChaseCamera"
	chase_camera.position = Vector3(0, 3.25, 7.0)
	chase_camera.rotation_degrees.x = -14.0
	chase_camera.fov = 70.0
	chase_camera.far = 500.0
	chase_camera.current = false
	add_child(chase_camera)

	headlight_spot = SpotLight3D.new()
	headlight_spot.position = Vector3(0, 0.85, -size.z * 0.48)
	headlight_spot.rotation_degrees.x = -6.0
	headlight_spot.spot_range = 28.0
	headlight_spot.spot_angle = 38.0
	headlight_spot.light_energy = 0.0
	headlight_spot.shadow_enabled = false
	add_child(headlight_spot)

	engine_audio = AudioStreamPlayer3D.new()
	var engine_stream = load("res://assets/audio/engine_loop.wav")
	if engine_stream:
		if engine_stream is AudioStreamWAV:
			engine_stream.loop_mode = AudioStreamWAV.LOOP_FORWARD
			engine_stream.loop_end = int(engine_stream.get_length() * engine_stream.mix_rate)
		engine_audio.stream = engine_stream
	engine_audio.unit_size = 7.0
	engine_audio.max_distance = 50.0
	engine_audio.volume_db = -18.0
	add_child(engine_audio)

	siren_audio = AudioStreamPlayer3D.new()
	var siren_stream = load("res://assets/audio/siren_loop.wav")
	if siren_stream:
		if siren_stream is AudioStreamWAV:
			siren_stream.loop_mode = AudioStreamWAV.LOOP_FORWARD
			siren_stream.loop_end = int(siren_stream.get_length() * siren_stream.mix_rate)
		siren_audio.stream = siren_stream
	siren_audio.unit_size = 12.0
	siren_audio.max_distance = 90.0
	siren_audio.volume_db = -12.0
	add_child(siren_audio)

	add_to_group("vehicles")
	set_physics_process(true)
	parked = true
	speed = 0.0
	velocity = Vector3.ZERO

func enter(by: Node) -> void:
	driver = by
	parked = false
	is_player_driven = true
	autopilot = false
	chase_camera.current = true
	if engine_audio and engine_audio.stream:
		engine_audio.play()
	if is_police and siren_audio and siren_audio.stream:
		siren_audio.play()

func exit_vehicle() -> void:
	driver = null
	parked = false
	is_player_driven = false
	speed = 0.0
	velocity = Vector3.ZERO
	if chase_camera:
		chase_camera.current = false
	if engine_audio:
		engine_audio.stop()
	if siren_audio:
		siren_audio.stop()

func honk() -> void:
	if horn_cooldown > 0.0:
		return
	horn_cooldown = 0.35
	if game and game.audio:
		game.audio.play_horn(global_position)

func _process(delta: float) -> void:
	horn_cooldown = maxf(0.0, horn_cooldown - delta)
	crash_cooldown = maxf(0.0, crash_cooldown - delta)
	if is_police and siren_red and siren_blue:
		siren_time += delta
		var phase := fmod(siren_time, 0.48)
		siren_red.visible = phase < 0.24
		siren_blue.visible = phase >= 0.24
	if headlight_spot:
		headlight_spot.light_energy = 4.0 if night else 0.0

func _physics_process(delta: float) -> void:
	if parked:
		return
	var gravity := float(ProjectSettings.get_setting("physics/3d/default_gravity"))
	if not is_on_floor():
		velocity.y -= gravity * delta
	else:
		velocity.y = -0.2

	if driver == null and not autopilot:
		speed = move_toward(speed, 0.0, brake_force * delta)
		velocity.x = 0.0
		velocity.z = 0.0
		move_and_slide()
		return

	var throttle := 0.0
	var steer_input := 0.0
	var handbrake := false
	if driver != null:
		throttle = Input.get_action_strength("move_forward") - Input.get_action_strength("move_back")
		steer_input = Input.get_action_strength("move_left") - Input.get_action_strength("move_right")
		handbrake = Input.is_action_pressed("sprint")
		if game and game.touch_move.length() > 0.12:
			throttle = -game.touch_move.y
			steer_input = -game.touch_move.x
	else:
		var ai := _ai_controls(delta)
		throttle = ai.x
		steer_input = ai.y

	var target_speed := 0.0
	if throttle > 0.04:
		target_speed = max_speed * clampf(throttle, 0.0, 1.0)
	elif throttle < -0.04:
		target_speed = reverse_speed * clampf(throttle, -1.0, 0.0)
	if handbrake:
		target_speed = 0.0
	var rate := brake_force if absf(target_speed) < absf(speed) else accel
	speed = move_toward(speed, target_speed, rate * delta)
	if handbrake:
		speed = move_toward(speed, 0.0, brake_force * 1.4 * delta)

	var grip := clampf(absf(speed) / 5.0, 0.0, 1.0)
	var steer_amount := steer_input * steer_rate * grip * signf(speed)
	rotate_y(steer_amount * delta)

	velocity.x = -global_transform.basis.z.x * speed
	velocity.z = -global_transform.basis.z.z * speed
	var before := global_position
	move_and_slide()
	if get_slide_collision_count() > 0:
		var impact := speed
		speed *= 0.42
		if impact > 7.0 and crash_cooldown <= 0.0:
			crash_cooldown = 0.5
			if game and game.audio:
				game.audio.play_crash(global_position, clampf(impact / 20.0, 0.2, 1.0))
		if absf(impact) > 12.0:
			health = maxf(0.0, health - absf(impact) * 0.25)
	if global_position.distance_to(before) < 0.005 and absf(speed) > 1.0:
		ai_stuck += delta
	else:
		ai_stuck = 0.0

	wheel_spin += speed * delta / maxf(wheel_radius, 0.1)
	for wheel in spin_wheels:
		wheel.rotation.x = wheel_spin
	for wheel in steer_wheels:
		wheel.rotation.y = steer_input * 0.46

	if chase_camera:
		var target_fov := 68.0 + clampf(absf(speed) / max_speed, 0.0, 1.0) * 8.0
		chase_camera.fov = lerpf(chase_camera.fov, target_fov, clampf(delta * 3.0, 0.0, 1.0))
		chase_camera.position.z = lerpf(chase_camera.position.z, 6.8 + absf(speed) * 0.035, clampf(delta * 2.0, 0.0, 1.0))

	if engine_audio and engine_audio.playing:
		engine_audio.pitch_scale = 0.72 + clampf(absf(speed) / max_speed, 0.0, 1.0) * 0.85
		engine_audio.volume_db = -18.0 if is_player_driven else -26.0

	if is_player_driven and absf(speed) > 4.0 and game:
		game.check_car_ped_collisions(self)

func _ai_controls(_delta: float) -> Vector2:
	return Vector2.ZERO

func drive_towards(target: Vector3, delta: float, desired_speed := 11.0) -> Vector2:
	var to := target - global_position
	to.y = 0.0
	var dist := to.length()
	if dist < 1.2:
		return Vector2(0.0, 0.0)
	var desired_yaw := atan2(-to.x, -to.z)
	var diff := wrapf(desired_yaw - rotation.y, -PI, PI)
	var steer := clampf(diff * 1.9, -1.0, 1.0)
	var throttle := 1.0
	if absf(diff) > 1.15:
		throttle = 0.38
	if dist < 10.0:
		throttle = clampf(dist / 10.0, 0.0, 0.6)
	if absf(speed) > desired_speed:
		throttle = -0.35
	if _forward_blocked(5.0 + absf(speed) * 0.25) and absf(diff) < 0.55:
		throttle = -0.7
	return Vector2(throttle, steer)

func _forward_blocked(distance: float) -> bool:
	var space := get_world_3d().direct_space_state
	if space == null:
		return false
	var from := global_position + Vector3(0, 0.75, 0) - global_transform.basis.z * 1.8
	var to := from - global_transform.basis.z * distance
	var query := PhysicsRayQueryParameters3D.create(from, to, 1 | 2 | 4 | 8, [get_rid()])
	var hit := space.intersect_ray(query)
	return not hit.is_empty()

func get_exit_position() -> Vector3:
	var space := get_world_3d().direct_space_state
	for side in [1.0, -1.0]:
		var offset := global_transform.basis.x * 2.3 * side
		var from := global_position + Vector3(0, 0.8, 0)
		var to := from + offset
		var query := PhysicsRayQueryParameters3D.create(from, to, 1)
		var hit := space.intersect_ray(query)
		if hit.is_empty():
			return global_position + offset + Vector3(0, 0.08, 0)
	return global_position + Vector3(0, 0.15, 0)

func set_night(value: bool) -> void:
	night = value
	if headlight_spot:
		headlight_spot.light_energy = 4.0 if night else 0.0

func get_speed_mph() -> float:
	return absf(speed) * 2.23694

func get_display_name() -> String:
	if is_police:
		return "RIVER CITY POLICE"
	if is_taxi:
		return "RIVER CITY TAXI"
	return vehicle_type.to_upper()

class_name Player
extends CharacterBody3D

## Third-person by default so the custom character is always visible.
## V switches to a true first-person view. All animation is procedural.

@export var walk_speed := 4.6
@export var sprint_speed := 8.0
@export var jump_speed := 4.9
@export var mouse_sensitivity := 0.0022

var game: Node
var head: Node3D
var camera: Camera3D
var interactor: RayCast3D
var model: Humanoid
var current_vehicle: Node = null
var controls_enabled := true
var first_person := false
var gravity := 9.8
var stamina := 100.0
var stamina_delay := 0.0
var footstep_timer := 0.0
var punch_timer := 0.0
var punch_cooldown := 0.0
var shake := 0.0
var camera_base := Vector3(0.55, 0.24, 3.35)

func setup(g: Node) -> void:
	game = g
	gravity = float(ProjectSettings.get_setting("physics/3d/default_gravity"))
	collision_layer = 2
	collision_mask = 1 | 4 | 8
	up_direction = Vector3.UP
	floor_snap_length = 0.35

	var col := CollisionShape3D.new()
	var capsule := CapsuleShape3D.new()
	capsule.radius = 0.35
	capsule.height = 1.8
	col.shape = capsule
	col.position.y = 0.9
	add_child(col)

	head = Node3D.new()
	head.name = "Head"
	head.position.y = 1.55
	add_child(head)

	camera = Camera3D.new()
	camera.name = "Camera3D"
	camera.position = camera_base
	camera.fov = 76.0
	camera.near = 0.05
	camera.far = 500.0
	camera.current = true
	head.add_child(camera)

	interactor = RayCast3D.new()
	interactor.name = "Interactor"
	interactor.target_position = Vector3(0, 0, -3.0)
	interactor.collision_mask = 1 | 4 | 8
	interactor.enabled = true
	interactor.add_exception(self)
	camera.add_child(interactor)

	model = Humanoid.new()
	model.name = "Character"
	add_child(model)
	model.setup({
		"skin": Color(0.42, 0.27, 0.18),
		"hair": Color(0.045, 0.038, 0.032),
		"shirt": Color(0.055, 0.058, 0.065),
		"pants": Color(0.06, 0.062, 0.07),
		"shoes": Color(0.045, 0.045, 0.05),
		"accent": Color(0.82, 0.64, 0.24),
		"hoodie": true,
		"chain": true,
		"hat": "",
		"glasses": false,
		"beard": false,
		"backpack": false,
		"vest": false,
		"height": 1.0,
		"width": 1.0
	})
	# White midsole on the black sneakers.
	model.model.scale = Vector3(1.0, 1.0, 1.0)
	set_first_person(false)
	Input.mouse_mode = Input.MOUSE_MODE_CAPTURED

func _unhandled_input(event: InputEvent) -> void:
	if game and game.paused:
		return
	if event.is_action_pressed("ui_cancel"):
		if game:
			game.toggle_pause()
		return
	if event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_LEFT:
		if Input.mouse_mode != Input.MOUSE_MODE_CAPTURED and not game.is_touch:
			Input.mouse_mode = Input.MOUSE_MODE_CAPTURED
		elif not first_person or true:
			attack()
	if event is InputEventMouseMotion and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
		look(event.relative)
	if event.is_action_pressed("interact"):
		if game:
			game.try_interact()
	if event.is_action_pressed("exit_vehicle"):
		if game:
			game.request_exit_vehicle()
	if event.is_action_pressed("honk"):
		if current_vehicle and current_vehicle.has_method("honk"):
			current_vehicle.honk()
	if event.is_action_pressed("toggle_view"):
		set_first_person(not first_person)
	if event.is_action_pressed("map"):
		if game and game.hud:
			game.hud.toggle_map()
	if event.is_action_pressed("help"):
		if game and game.hud:
			game.hud.toggle_help()
	if event.is_action_pressed("radio_next"):
		if game and game.audio:
			game.audio.next_station()
	if event.is_action_pressed("restart"):
		if game and game.hud and game.hud.help_visible:
			get_tree().reload_current_scene()

func look(relative: Vector2) -> void:
	if current_vehicle != null or not controls_enabled:
		return
	rotate_y(-relative.x * mouse_sensitivity)
	head.rotation.x = clampf(head.rotation.x - relative.y * mouse_sensitivity, deg_to_rad(-82.0), deg_to_rad(82.0))

func _physics_process(delta: float) -> void:
	if not controls_enabled or current_vehicle != null:
		velocity = Vector3.ZERO
		if model:
			model.animate(delta, 0.0, true)
		return
	if not is_on_floor():
		velocity.y -= gravity * delta
	if Input.is_action_just_pressed("jump") and is_on_floor():
		velocity.y = jump_speed
	var input_dir := Input.get_vector("move_left", "move_right", "move_forward", "move_back")
	if game and game.touch_move.length() > 0.1:
		input_dir = game.touch_move
	var direction := (global_transform.basis * Vector3(input_dir.x, 0.0, input_dir.y)).normalized()
	var sprinting := Input.is_action_pressed("sprint") and input_dir.length() > 0.1 and stamina > 2.0
	var speed := sprint_speed if sprinting else walk_speed
	if sprinting:
		stamina = maxf(0.0, stamina - 18.0 * delta)
		stamina_delay = 1.0
	else:
		stamina_delay = maxf(0.0, stamina_delay - delta)
		if stamina_delay <= 0.0:
			stamina = minf(100.0, stamina + 14.0 * delta)
	velocity.x = direction.x * speed
	velocity.z = direction.z * speed
	move_and_slide()
	var horiz := Vector2(velocity.x, velocity.z).length()
	if model:
		model.animate(delta, horiz, is_on_floor())
	if horiz > 0.5 and is_on_floor():
		footstep_timer -= delta
		if footstep_timer <= 0.0:
			footstep_timer = 0.34 if sprinting else 0.48
			if game and game.audio:
				game.audio.play_footstep(global_position, 0.7 if sprinting else 0.5)
	else:
		footstep_timer = 0.0

func _process(delta: float) -> void:
	if game and game.touch_look.length() > 0.1:
		look(game.touch_look)
		game.touch_look = Vector2.ZERO
	punch_cooldown = maxf(0.0, punch_cooldown - delta)
	shake = maxf(0.0, shake - delta * 2.5)
	if current_vehicle == null and controls_enabled:
		_update_camera(delta)
	# Subtle breathing camera motion.
	if camera and not first_person:
		camera.position.y = camera_base.y + sin(Time.get_ticks_msec() * 0.0014) * 0.012
	if shake > 0.0 and camera:
		camera.h_offset = sin(Time.get_ticks_msec() * 0.09) * shake * 0.08
		camera.v_offset = cos(Time.get_ticks_msec() * 0.11) * shake * 0.08
	elif camera:
		camera.h_offset = 0.0
		camera.v_offset = 0.0

func _update_camera(delta: float) -> void:
	if not camera or not head:
		return
	if first_person:
		camera.position = camera.position.lerp(Vector3(0, 0, 0), clampf(delta * 12.0, 0.0, 1.0))
		if model:
			model.visible = false
		return
	if model:
		model.visible = true
	var desired := camera_base
	var from := head.global_position
	var desired_global := head.to_global(desired)
	var space := get_world_3d().direct_space_state
	if space:
		var query := PhysicsRayQueryParameters3D.create(from, desired_global, 1, [get_rid()])
		var hit := space.intersect_ray(query)
		if not hit.is_empty():
			var local_hit: Vector3 = head.to_local(hit.position)
			var dist := local_hit.length()
			if dist < desired.length():
				desired = local_hit.normalized() * maxf(0.45, dist - 0.20)
				if dist < 1.0 and model:
					model.visible = false
	camera.position = camera.position.lerp(desired, clampf(delta * 14.0, 0.0, 1.0))

func set_first_person(value: bool) -> void:
	first_person = value
	if camera:
		camera.position = Vector3(0, 0, 0) if value else camera_base
	if model and current_vehicle == null:
		model.visible = not value
	if game and game.hud:
		game.hud.set_crosshair(value)

func attack() -> void:
	if current_vehicle != null or punch_cooldown > 0.0 or not controls_enabled:
		return
	punch_cooldown = 0.42
	shake = 0.8
	if model:
		model.punch()
	if game and game.audio:
		game.audio.play_whoosh(global_position)
	var from := camera.global_position
	var to := from - camera.global_transform.basis.z * 2.4
	var space := get_world_3d().direct_space_state
	if space == null:
		return
	var query := PhysicsRayQueryParameters3D.create(from, to, 8, [get_rid()])
	var hit := space.intersect_ray(query)
	if not hit.is_empty():
		var target = hit.collider
		if target and target.has_method("hit_by_player"):
			target.hit_by_player(self)
			if game:
				game.on_assault()
		else:
			if game and game.audio:
				game.audio.play_impact(hit.position, 0.35)

func enter_vehicle(v: Node) -> void:
	current_vehicle = v
	controls_enabled = false
	visible = false
	collision_layer = 0
	collision_mask = 0
	velocity = Vector3.ZERO
	if camera:
		camera.current = false
	v.enter(self)

func exit_vehicle(v: Node) -> void:
	current_vehicle = null
	global_position = v.get_exit_position()
	visible = true
	collision_layer = 2
	collision_mask = 1 | 4 | 8
	controls_enabled = true
	if camera:
		camera.current = true
	v.exit_vehicle()
	set_first_person(first_person)
	Input.mouse_mode = Input.MOUSE_MODE_CAPTURED

func get_eye_position() -> Vector3:
	return camera.global_position if camera else global_position + Vector3(0, 1.55, 0)

